function crearPerfil(nombre, edad) {
  nombre = nombre || 'Invitado';
  edad = edad || 18;
  return { nombre, edad };
}

function componer(valor, primero, segundo) {
  return segundo(primero(valor));
}

const duplicar = numero => numero * 2;
const incrementar = numero => numero + 1;

function procesar(valor, transformar, notificar) {
  const resultado = transformar(valor);
  notificar(resultado);
  return resultado;
}

const limpiar = texto => texto.trim();
const registrar = valor => `guardado:${valor}`;

function pipeline(valor, primero, segundo) {
  const intermedio = primero(valor);
  segundo(intermedio);
  return intermedio;
}
